(function () {
  const vscode = acquireVsCodeApi();
  const body = document.getElementById('body');
  window.addEventListener('message', (e) => { if (e.data && typeof e.data.body === 'string') { body.innerHTML = e.data.body; } });
  body.addEventListener('click', (e) => {
    const b = e.target.closest('button');
    if (!b || b.disabled) { return; }
    if (b.dataset.all) { vscode.postMessage({ all: true }); }
    else if (b.dataset.refresh) { vscode.postMessage({ refresh: true }); }
    else if (b.dataset.run) { vscode.postMessage({ run: b.dataset.run }); }
    else if (b.dataset.adv) { vscode.postMessage({ adv: b.dataset.adv }); }
  });
})();
